quiz.code:
#include <stdio.h>

void change(int value)
{
    value++;
    printf("inside:%d\n", value);
}

int main(void)
{
    int value = 8;
    change(value);
    printf("%d\n", value);
    return 0;
}

#include <stdio.h>

void change(int *value)
{
    *value += 3;
}

int main(void)
{
    int value = 8;
    change(&value);
    printf("%d\n", value);
    return 0;
}

#include <stdio.h>

void redirect(int *p, int *q)
{
    p = q;
    *p = 20;
}

int main(void)
{
    int a = 4, b = 9;
    redirect(&a, &b);
    printf("%d %d\n", a, b);
    return 0;
}

