A parameter copy is incremented. Which caller value survives?

#include <stdio.h>

void change(int value)
{
    value++;
    printf("inside:%d\n", value);
}

int main(void)
{
    int value = 8;
    change(value);
    printf("%d\n", value);
    return 0;
}
